template <int N>
struct Factorial {
    static const int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    static const int value = 1;
};
// Factorial<5>::value resolves at compile time

constexpr long long CT_Factorial(int n) {
    return (n == 0) ? 1 : n * CT_Factorial(n - 1);
}

[[maybe_unused]]
constexpr auto result = CT_Factorial(10);
// Compile-Time Function Execution (CTFE) via constexpr

template <typename T>
struct has_foo {
private:
    template <typename C>
    static auto check(int) -> decltype(std::declval<C>().foo(), std::true_type{});

    template <typename>
    static std::false_type check(...);

public:
    static constexpr bool value = decltype(check<T>(0))::value;
};
// SFINAE based evaluation of expression validity
// requires std::true_type, std::false_type, std::declval
